    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 86-year-old male is brought to the clinic by a family member due to progressive memory loss over the past 3 years. The family reports that the patient frequently misplaces items, repeats questions, and has difficulty managing finances. Cognitive testing reveals a MoCA score of **22/30**. A brain MRI shows bilateral **hippocampal and temporoparietal** atrophy. Which of the following describes the characteristic histopathological findings and first-line pharmacological treatment for this condition?', '["Extracellular amyloid-beta plaques and intracellular hyperphosphorylated tau neurofibrillary tangles; treat with cholinesterase inhibitors (e.g., Donepezil)", "Perivascular lymphocytic cuffs and demyelinating plaques; treat with interferon-beta", "Ubiquitin and tau-positive inclusions in the frontotemporal lobes; treat with high-dose atypical antipsychotics", "Spongiform encephalopathy with vacuolation of neurons; treat with acyclovir and corticosteroids", "Alpha-synuclein cytoplasmic inclusions (Lewy bodies) in the substantia nigra; treat with high-dose levodopa/carbidopa"]'::jsonb, 0, 'This patient''''s clinical presentation—insidious onset, slowly progressive memory impairment, and bilateral **hippocampal and temporoparietal** atrophy on brain MRI—is diagnostic of **Alzheimer''''s disease (AD)**, the most common cause of dementia in older adults (60-80% of cases). The hallmark histopathological features include: (1) **Extracellular amyloid-beta (Aβ) plaques** derived from abnormal cleavage of amyloid precursor protein (APP) by β-secretase and γ-secretase, and (2) **Intracellular neurofibrillary tangles (NFTs)** consisting of **hyperphosphorylated tau protein**. These accumulate preferentially in the entorhinal cortex and hippocampus early in the disease. First-line pharmacological management for mild-to-moderate AD includes **cholinesterase inhibitors** (Donepezil, Galantamine, or Rivastigmine). Memantine (NMDA antagonist) is added for moderate-to-severe disease. (Ref: Hazzard''''s Ch. 72; First Aid Step 2 CK)'),
    (v_topic_id, 'A 91-year-old woman is brought to the clinic by a family member due to progressive memory loss over the past 4 years. The family reports that the patient frequently misplaces items, repeats questions, and has difficulty managing finances. Cognitive testing reveals a MoCA score of **19/30**. A brain MRI shows bilateral **medial temporal lobe and parietal** atrophy. Which of the following describes the characteristic histopathological findings and first-line pharmacological treatment for this condition?', '["Perivascular lymphocytic cuffs and demyelinating plaques; treat with interferon-beta", "Alpha-synuclein cytoplasmic inclusions (Lewy bodies) in the substantia nigra; treat with high-dose levodopa/carbidopa", "Spongiform encephalopathy with vacuolation of neurons; treat with acyclovir and corticosteroids", "Ubiquitin and tau-positive inclusions in the frontotemporal lobes; treat with high-dose atypical antipsychotics", "Extracellular amyloid-beta plaques and intracellular hyperphosphorylated tau neurofibrillary tangles; treat with cholinesterase inhibitors (e.g., Donepezil)"]'::jsonb, 4, 'This patient''''s clinical presentation—insidious onset, slowly progressive memory impairment, and bilateral **medial temporal lobe and parietal** atrophy on brain MRI—is diagnostic of **Alzheimer''''s disease (AD)**, the most common cause of dementia in older adults (60-80% of cases). The hallmark histopathological features include: (1) **Extracellular amyloid-beta (Aβ) plaques** derived from abnormal cleavage of amyloid precursor protein (APP) by β-secretase and γ-secretase, and (2) **Intracellular neurofibrillary tangles (NFTs)** consisting of **hyperphosphorylated tau protein**. These accumulate preferentially in the entorhinal cortex and hippocampus early in the disease. First-line pharmacological management for mild-to-moderate AD includes **cholinesterase inhibitors** (Donepezil, Galantamine, or Rivastigmine). Memantine (NMDA antagonist) is added for moderate-to-severe disease. (Ref: Hazzard''''s Ch. 72; First Aid Step 2 CK)'),
